css:
/* Обратная связь поля. Ошибку сообщают сразу три вещи — цвет рамки, значок и текст; движение только подчёркивает.
   Под текст ошибки место занято заранее (одна строка): появление не сдвигает форму. Анимируются только transform и opacity. */
.ffb { display: grid; gap: 4px; max-width: 440px; }
.ffb__label { display: block; margin-bottom: 6px; font-size: 14px; color: var(--text-muted, #555b66); }
.ffb__control { position: relative; }
.ffb__input {
  width: 100%; min-height: 48px; box-sizing: border-box;
  padding: 12px 44px 12px 14px;                  /* справа место под значок */
  font: inherit; font-size: 16px;                /* 16px — iPhone не увеличивает страницу при фокусе */
  color: var(--text, #15171c); background: var(--background, #ffffff);
  border: 1px solid var(--border, #c9ced8); border-radius: 12px;
}
.ffb__input:focus-visible { outline: 3px solid var(--primary, #2446d8); outline-offset: 1px; }
/* Ошибка: цвет рамки меняется сразу (без анимации) + внутренняя обводка той же толщины — поле не меняет размер */
.ffb__input[aria-invalid="true"] { border-color: var(--error, #b42318); box-shadow: inset 0 0 0 1px var(--error, #b42318); }
.ffb__icon {
  position: absolute; right: 14px; top: 50%; width: 20px; height: 20px; margin-top: -10px;
  fill: none; stroke: var(--error, #b42318); stroke-width: 2; stroke-linecap: round;
  pointer-events: none;
  opacity: 0; transform: scale(.6);
  transition: opacity 150ms cubic-bezier(.4, 0, 1, 1), transform 150ms cubic-bezier(.4, 0, 1, 1);
}
.ffb__field.is-invalid .ffb__icon {
  opacity: 1; transform: none;
  transition: opacity 150ms cubic-bezier(.2, 0, 0, 1) 50ms, transform 150ms cubic-bezier(.2, 0, 0, 1) 50ms;
}
.ffb__control--check { display: flex; gap: 10px; align-items: flex-start; font-size: 14px; line-height: 1.4; }
.ffb__check { flex: none; width: 24px; height: 24px; margin: 0; accent-color: var(--primary, #2446d8); }
.ffb__check[aria-invalid="true"] { outline: 2px solid var(--error, #b42318); outline-offset: 2px; }
.ffb__control--check a { color: var(--link, #1d4ed8); }
.ffb__err {
  min-height: 1.45em; margin: 4px 0 8px;         /* место под одну строку занято заранее; тексты ошибок — до 40 знаков */
  font-size: 14px; line-height: 1.45; color: var(--error, #b42318);
  opacity: 0; transform: translateY(-4px);
  transition: opacity 120ms cubic-bezier(.4, 0, 1, 1), transform 120ms cubic-bezier(.4, 0, 1, 1);
}
.ffb__field.is-invalid .ffb__err { opacity: 1; transform: none; transition: opacity 200ms cubic-bezier(.2, 0, 0, 1), transform 200ms cubic-bezier(.2, 0, 0, 1); }
.ffb__btn {
  justify-self: start; min-height: 52px; padding: 14px 28px;
  border: 0; border-radius: 999px; cursor: pointer;
  background: var(--primary, #2446d8); color: var(--on-primary, #ffffff); font: inherit; font-weight: 600;
}
.ffb__btn:focus-visible { outline: 3px solid var(--text, #15171c); outline-offset: 3px; }
/* Встряска при попытке отправить: ±12px, затухающие колебания за 360ms, без перелёта — поле встаёт ровно на место */
@keyframes ffb-shake {
  0%, 100% { transform: translateX(0); }
  15% { transform: translateX(-12px); }
  35% { transform: translateX(10px); }
  55% { transform: translateX(-6px); }
  75% { transform: translateX(3px); }
}
.ffb__control.is-shake { animation: ffb-shake 360ms cubic-bezier(.36, .07, .19, .97); }
/* Уменьшение движения (уровень «смягчить»): без встряски и сдвигов; рамка, значок и текст появляются проявлением 150ms */
@media (prefers-reduced-motion: reduce) {
  .ffb__control.is-shake { animation: none; }
  .ffb__icon, .ffb__err { transform: none !important; }
  .ffb__field.is-invalid .ffb__icon, .ffb__field.is-invalid .ffb__err { transition: opacity 150ms linear; }
}

js:
// Обратная связь полей формы: без зависимостей. Ошибки — только при попытке отправить и после ухода с поля, не во время набора.
(() => {
  const reduce = matchMedia('(prefers-reduced-motion: reduce)');
  const msg = (el) => { // текст ошибки или '' — всегда человеческими словами, не системным «Заполните это поле»
    if (el.validity.valueMissing) return el.dataset.msgMissing || 'Заполните это поле';
    const digits = el.value.replace(/\D/g, '').length;
    if (el.hasAttribute('data-ffb-phone') && (digits < 10 || digits > 15)) return el.dataset.msgBad || 'Проверьте номер телефона';
    return el.validity.valid ? '' : el.dataset.msgBad || el.validationMessage;
  };
  const mark = (el, text) => { // показать или снять ошибку поля
    const field = el.closest('.ffb__field'), err = field && field.querySelector('.ffb__err');
    if (!err) return;
    if (text) { el.setAttribute('aria-invalid', 'true'); err.textContent = text; } else el.removeAttribute('aria-invalid');
    field.classList.toggle('is-invalid', !!text);
    // исправлено: текст гаснет 120ms и стирается — иначе диктор прочтёт старую ошибку через aria-describedby
    if (!text) setTimeout(() => { if (!field.classList.contains('is-invalid')) err.textContent = ''; }, 150);
  };
  const shake = (el) => {
    const c = el.closest('.ffb__control');
    if (!c || reduce.matches) return;
    c.classList.remove('is-shake'); void c.offsetWidth; c.classList.add('is-shake'); // перезапуск анимации
    c.addEventListener('animationend', () => c.classList.remove('is-shake'), { once: true });
  };
  document.querySelectorAll('form[data-ffb]').forEach((f) => { f.noValidate = true; }); // системные подсказки заменяем своими
  // Фаза перехвата на document: срабатывает раньше любых обработчиков отправки на самой форме (form-success и т. п.)
  document.addEventListener('submit', (e) => {
    const form = e.target.closest && e.target.closest('form[data-ffb]');
    if (!form) return;
    const bad = [...form.elements].filter((el) => el.willValidate && msg(el));
    if (!bad.length) return; // всё верно — отправка идёт дальше как обычно
    e.preventDefault(); e.stopPropagation();
    bad.forEach((el, i) => { mark(el, msg(el)); setTimeout(() => shake(el), i * 30); }); // очередь 30ms
    bad[0].focus({ preventScroll: true }); // диктор прочтёт подпись поля и текст ошибки (aria-describedby)
    bad[0].scrollIntoView({ block: 'center', behavior: reduce.matches ? 'auto' : 'smooth' });
  }, true);
  document.addEventListener('focusout', (e) => { const el = e.target; // ушёл с поля: показать ошибку тихо, без встряски
    if (el.form && el.form.matches('[data-ffb]') && el.willValidate && ((el.type !== 'checkbox' && el.value) || el.hasAttribute('aria-invalid'))) mark(el, msg(el)); });
  document.addEventListener('input', (e) => { const el = e.target; // исправил — ошибка уходит сразу, новые во время набора не показываем
    if (el.hasAttribute && el.hasAttribute('aria-invalid') && !msg(el)) mark(el, ''); });
})();
